"""Export the verified 2 s autonomous CPG trajectory for browser inspection."""
from __future__ import annotations
import hashlib,json
from pathlib import Path
import mujoco,numpy as np
from scipy.signal import find_peaks
from calibrate_official_running_contact_compliance import make_model
from evaluate_official_running_dynamic_replay import FPS,MODEL_TO_MM,ROOT,contact_state

SOURCE=ROOT/"results/official-running-cpg-recovery-20260924/rollouts.npz";SOURCE_REPORT=ROOT/"results/official-running-cpg-recovery-20260924/report.json";OUT=ROOT/"results/official-running-cpg-recovery-20260924/cpg-walking-replay.json";HTML=ROOT/"cpg_walking_replay.html"

def main():
 report=json.loads(SOURCE_REPORT.read_text());a=np.load(SOURCE);qpos=np.asarray(a["canonical_qpos"]);controls=np.asarray(a["canonical_control"]);model,ground,claws,_=make_model(.005);data=mujoco.MjData(model)
 body_ids=[i for i in range(1,model.nbody) if model.body(i).name and model.body(i).name!="floor"];index={bid:i for i,bid in enumerate(body_ids)};names=[model.body(i).name for i in body_ids];edges=[]
 for bid in body_ids:
  parent=int(model.body_parentid[bid])
  if parent in index:edges.append([index[parent],index[bid]])
 frames=[];contacts=[];feet=[]
 site_names=("claw_T1_left","claw_T1_right","claw_T2_left","claw_T2_right","claw_T3_left","claw_T3_right");site_ids=[mujoco.mj_name2id(model,mujoco.mjtObj.mjOBJ_SITE,x) for x in site_names]
 for q in qpos:
  data.qpos[:]=q;mujoco.mj_forward(model,data);frames.append((data.xpos[body_ids]*MODEL_TO_MM).round(5).tolist());c,_,_=contact_state(data,ground,claws);contacts.append(c.astype(int).tolist());feet.append((data.site_xpos[site_ids]*MODEL_TO_MM).copy())
 feet=np.asarray(feet);cumulative=np.zeros((len(qpos),6),int)
 for leg in range(6):
  z=feet[:,leg,2];peaks,_=find_peaks(z-np.percentile(z,5),prominence=max(.035,.15*np.ptp(z)),distance=round(.020*FPS));cumulative[:,leg]=np.searchsorted(peaks,np.arange(len(qpos)),side="right")
 center_name="Thorax" if "Thorax" in names else names[0];center=names.index(center_name);xy=qpos[:,:2]*MODEL_TO_MM;speed=np.r_[0,np.linalg.norm(np.diff(xy,axis=0),axis=1)*FPS];direction=xy[-1]-xy[0];direction/=max(np.linalg.norm(direction),1e-12);forward=(xy-xy[0])@direction;period=json.loads((ROOT/"results/official-running-cpg-policy-20260924/report.json").read_text())["source_cycle"]["period_frames"]
 replay={"title":"神经 CPG 标准起点自主行走","source_sha256":hashlib.sha256(SOURCE.read_bytes()).hexdigest(),"report_sha256":hashlib.sha256(SOURCE_REPORT.read_bytes()).hexdigest(),"fps":FPS,"period_frames":period,"names":names,"edges":edges,"center_index":center,"floor_z":float(np.min(feet[:,:,2])),"world_center":np.mean(np.asarray(frames)[:,center],axis=0).round(5).tolist(),"frames":frames,"contact":contacts,"speed_mm_s":speed.round(3).tolist(),"forward_mm":forward.round(4).tolist(),"cumulative_cycles":cumulative.tolist(),"control_rms":np.sqrt(np.mean(controls*controls,axis=1)).round(6).tolist(),"cpg_sin":np.sin(2*np.pi*np.arange(len(qpos))/period).round(6).tolist(),"cpg_cos":np.cos(2*np.pi*np.arange(len(qpos))/period).round(6).tolist(),"body_contact":a["canonical_body_contact"].astype(int).tolist(),"verification":report["standard_start"]}
 OUT.write_text(json.dumps(replay,separators=(",",":"),allow_nan=False)+"\n");HTML.write_text(html(str(OUT.relative_to(ROOT))));print(json.dumps({"frames":len(qpos),"bodies":len(names),"edges":len(edges),"distance_2s_mm":report["standard_start"]["result"]["distance_2s_mm"],"body_contact_fraction":report["standard_start"]["result"]["body_contact_fraction"],"json":str(OUT),"html":str(HTML)},ensure_ascii=False))

def html(data_path):
 return '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>神经CPG自主行走验收</title><style>:root{--bg:#071018;--panel:#0d1b27;--ink:#eaf5ff;--muted:#8ba5b8;--cyan:#56d6ff;--green:#69e5a0;--gold:#ffb454}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 30% 15%,#153047,#071018 58%);color:var(--ink);font:15px system-ui,sans-serif;overflow:hidden}#view{position:fixed;inset:0;width:100%;height:100%;cursor:grab}.panel{position:fixed;left:18px;top:16px;width:min(620px,calc(100vw - 36px));background:#071018e8;border:1px solid #29445a;border-radius:14px;padding:14px 16px;backdrop-filter:blur(12px)}h1{font-size:20px;margin:0 0 5px}.ok{color:#69e5a0}.warn{color:#ffca81}.muted{color:var(--muted);font-size:13px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-top:10px}.v{font-size:18px;color:var(--cyan);font-variant-numeric:tabular-nums}.k{font-size:10px;color:var(--muted)}.osc{display:flex;gap:8px;margin-top:8px}.bar{height:7px;flex:1;background:#233a4b;border-radius:5px;overflow:hidden}.bar i{display:block;height:100%;width:50%;background:var(--gold);transition:width .03s}.controls{position:fixed;left:18px;bottom:18px;display:flex;gap:8px;background:#071018e8;border:1px solid #29445a;padding:9px;border-radius:12px}button{border:1px solid #38546a;background:#102638;color:var(--ink);border-radius:8px;padding:8px 12px}.legend{position:fixed;right:18px;bottom:18px;background:#071018e8;border:1px solid #29445a;border-radius:12px;padding:10px 13px;color:var(--muted)}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}</style></head><body><canvas id="view"></canvas><section class="panel"><h1>神经 CPG 标准起点自主行走 · <span class="ok">2 秒验收通过</span></h1><div class="muted">内部振荡状态 + 本体感觉 + 六足接触 → 56 路执行器 → MuJoCo 自由身体。无根节点推进、无录像姿态回放、无运行时参考轨迹。</div><div class="stats"><div><div class="v" id="time">0.000 s</div><div class="k">时间</div></div><div><div class="v" id="forward">0.00 mm</div><div class="k">净前进</div></div><div><div class="v" id="speed">0.0 mm/s</div><div class="k">瞬时速度</div></div><div><div class="v" id="cycles">0/0/0/0/0/0</div><div class="k">六腿周期</div></div><div><div class="v" id="contact">0/6</div><div class="k">足接触</div></div></div><div class="osc"><span>CPG sin</span><div class="bar"><i id="sin"></i></div><span>CPG cos</span><div class="bar"><i id="cos"></i></div></div><div class="muted warn">能力边界：该页验证标准起点；陌生初态恢复仍未通过，CPG 是来源数据训练的工程神经模型，不冒充已重建的生物 VNC。</div></section><div class="controls"><button id="play">暂停</button><button id="restart">重播</button><button id="follow">跟随身体：开</button></div><div class="legend"><div><span class="dot" style="background:#56d6ff"></span>左侧身体链</div><div><span class="dot" style="background:#69e5a0"></span>右侧身体链</div><div><span class="dot" style="background:#ffb454"></span>轨迹</div><div>拖动旋转 · 滚轮缩放</div></div><script>fetch("DATA").then(r=>r.json()).then(init);function init(D){const c=document.querySelector('#view'),x=c.getContext('2d');let W,H,ratio=1;function size(){ratio=devicePixelRatio||1;W=innerWidth;H=innerHeight;c.width=W*ratio;c.height=H*ratio;c.style.width=W+'px';c.style.height=H+'px';x.setTransform(ratio,0,0,ratio,0,0)}addEventListener('resize',size);size();let yaw=-.75,pitch=.48,zoom=62,playing=true,follow=true,frame=0,last=performance.now(),drag=null;c.onpointerdown=e=>{drag=[e.clientX,e.clientY,yaw,pitch];c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(drag){yaw=drag[2]+(e.clientX-drag[0])*.008;pitch=Math.max(-.05,Math.min(1.35,drag[3]+(e.clientY-drag[1])*.006))}};c.onpointerup=()=>drag=null;c.onwheel=e=>{zoom=Math.max(20,Math.min(180,zoom*Math.exp(-e.deltaY*.001)));e.preventDefault()},{passive:false};play.onclick=()=>{playing=!playing;play.textContent=playing?'暂停':'继续'};restart.onclick=()=>frame=0;document.querySelector('#follow').onclick=()=>{follow=!follow;document.querySelector('#follow').textContent='跟随身体：'+(follow?'开':'关')};function rot(p,o){let X=p[0]-o[0],Y=p[1]-o[1],Z=p[2]-o[2],cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch),a=cy*X-sy*Y,b=sy*X+cy*Y;return[W*.5+a*zoom,H*.64-(cp*Z-sp*b)*zoom,b*cp+Z*sp]}function draw(){requestAnimationFrame(draw);let now=performance.now(),dt=(now-last)/1000;last=now;if(playing)frame=(frame+dt*D.fps)%D.frames.length;let i=Math.floor(frame),P=D.frames[i],center=follow?P[D.center_index]:D.world_center;x.clearRect(0,0,W,H);let g=x.createLinearGradient(0,0,0,H);g.addColorStop(0,'#102b40');g.addColorStop(1,'#050b10');x.fillStyle=g;x.fillRect(0,0,W,H);x.strokeStyle='#23445a';x.lineWidth=1;for(let k=-12;k<=12;k++){for(let axis=0;axis<2;axis++){let a=center.slice(),b=center.slice();a[axis]+=k;a[1-axis]-=12;b[axis]+=k;b[1-axis]+=12;a[2]=b[2]=D.floor_z;let A=rot(a,center),B=rot(b,center);x.beginPath();x.moveTo(A[0],A[1]);x.lineTo(B[0],B[1]);x.stroke()}}let trail=[];for(let q=0;q<=i;q+=8)trail.push(rot(D.frames[q][D.center_index],center));x.strokeStyle='#ffb454';x.lineWidth=2;x.beginPath();trail.forEach((p,j)=>j?x.lineTo(p[0],p[1]):x.moveTo(p[0],p[1]));x.stroke();let V=P.map(p=>rot(p,center));for(const [a,b]of D.edges){let A=V[a],B=V[b],n=D.names[a]+D.names[b];x.strokeStyle=n.includes('left')?'#56d6ff':n.includes('right')?'#69e5a0':'#d7e4ec';x.lineWidth=3;x.beginPath();x.moveTo(A[0],A[1]);x.lineTo(B[0],B[1]);x.stroke()}for(let j=0;j<V.length;j++){x.fillStyle='#eaf5ff';x.beginPath();x.arc(V[j][0],V[j][1],2.4,0,Math.PI*2);x.fill()}time.textContent=(i/D.fps).toFixed(3)+' s';forward.textContent=D.forward_mm[i].toFixed(2)+' mm';speed.textContent=D.speed_mm_s[i].toFixed(1)+' mm/s';cycles.textContent=D.cumulative_cycles[i].join('/');contact.textContent=D.contact[i].reduce((a,b)=>a+b,0)+'/6';document.querySelector('#sin').style.width=((D.cpg_sin[i]+1)*50)+'%';document.querySelector('#cos').style.width=((D.cpg_cos[i]+1)*50)+'%'}draw()}</script></body></html>'''.replace('DATA',data_path)

if __name__=="__main__":main()
